import java.util.*;
import java.util.function.*;

public class Main {
    static class RequestScope {
        Map<String, Object> current = new HashMap<>();
        Object get(String name, Supplier<Object> f) { return current.computeIfAbsent(name, k -> f.get()); }
        void endRequest() { current.clear(); }
    }
    static class Bean { static int n = 0; int id = ++n; }
    public static void main(String[] args) {
        RequestScope rs = new RequestScope();
        Bean r1a = (Bean) rs.get("b", Bean::new);
        Bean r1b = (Bean) rs.get("b", Bean::new);
        System.out.println("request1 same: " + (r1a == r1b));
        rs.endRequest();
        Bean r2 = (Bean) rs.get("b", Bean::new);
        System.out.println("request2 != request1: " + (r2 != r1a));
        System.out.println("total instances: " + Bean.n);
    }
}
